export type ValueJSON = Float | Bool | Text | Vec2 | Vec3 | Vec4 | Quat | ColorRgba | Vector | EnumVal | RecordVal | ArrayVal | ListVal | TupleVal | Transform | NormalizedValue | number | string | boolean;
export type ValueInput = ValueJSON | number[];
