export declare function valueAsVec3(value: ValueJSON | undefined | null): [number, number, number] | undefined;
export declare function valueAsVector(value: ValueJSON | undefined | null): number[] | undefined;
export declare function valueAsBool(value: ValueJSON | undefined | null): boolean | undefined;
export declare function valueAsQuat(value: ValueJSON | undefined | null): [number, number, number, number] | undefined;
